// Fusionar todos los datos recopilados en un objeto unificado
const input    = $('Validar Formato TXN').first().json;
const txn      = $('Obtener Transacción').first().json || {};
const logsData = $('Obtener Logs').first().json || {};
const policies = $('Buscar Políticas').first().json || {};
const cases    = $('Buscar Casos Similares').first().json || {};

const slaCrudo = $('Verificar SLA').first().json || {};

// Merchant y cliente: los flags ya vienen calculados por la API.
// Los umbrales viven en domain/constants.py, no en n8n.
let merchant = {};
try {
  merchant = $('Riesgo del Comercio').first().json;
} catch (e) { merchant = { error: e.message }; }

let client = {};
try {
  client = $('Historial del Cliente').first().json;
} catch (e) { client = { error: e.message }; }
// Los nodos de RAG siguen adelante si fallan (onError: continueRegularOutput),
// asi que su fallo llega aca como un item con `error` y hasta ahora se perdia:
// `results || []` hace que "no pude buscar" se lea igual que "no hay ninguno",
// que es la conclusion opuesta. Se anota para que el informe lo declare.
// `error` no siempre es un string: cuando un nodo HTTP continúa tras fallar,
// n8n pone ahí un objeto, y interpolarlo daba «[object Object]».
const porQue = (e) => (typeof e === 'string' ? e : (e && (e.message || e.reason)) || JSON.stringify(e));

const avisosDeContexto = [
  [policies,   'No se pudieron recuperar las políticas aplicables'],
  [cases,      'No se pudieron recuperar los precedentes similares'],
  [merchant, 'No se pudo recuperar el perfil de riesgo del comercio'],
  [client,   'No se pudo recuperar el historial del cliente'],
  [slaCrudo,   'No se pudo medir el plazo del caso'],
  [logsData,   'No se pudieron recuperar los logs de la transacción'],
].filter(([fuente]) => fuente && fuente.error)
 .map(([fuente, frase]) => `${frase}: ${porQue(fuente.error)}`);

// Un SLA que falló NO es un SLA de cero días: si viaja, el informe afirma un
// incumplimiento que nadie midió y el evaluador de políticas razona sobre un
// objeto de error bajo el título «plazos ya medidos». Se corta acá.
const sla = slaCrudo.error ? {} : slaCrudo;

const slaStatus = sla.within_sla != null
  ? (sla.within_sla
    ? `dentro de SLA (${sla.days_elapsed}d / ${sla.sla_limit_days}d)`
    : `FUERA de SLA (${sla.days_elapsed}d / ${sla.sla_limit_days}d)`)
  : 'SLA no calculado';

const agentAnalysis = [
  `Caso ${input.transaction_id}: ${txn.merchant || 'N/A'}, USD ${txn.amount_usd || 0},`,
  `canal ${txn.channel || 'N/A'}, país ${txn.country || 'N/A'}, score fraude ${txn.fraud_score ?? 'N/A'}.`,
  `Motivo: ${input.motivo || 'no especificado'}.`,
  `SLA: ${slaStatus}.`,
  `Cliente VIP: ${input.cliente_vip ? 'sí' : 'no'}.`,
  `Políticas encontradas: ${(policies.results || []).length}.`,
  `Casos similares: ${(cases.results || []).length}.`,
].join(' ');

return [{
  json: {
    transaction_id:  input.transaction_id,
    motivo:          input.motivo,
    cliente_vip:     input.cliente_vip,
    tx_data:         txn,
    logs:            logsData.logs || [],
    policies:        policies.results || [],
    similar_cases:   cases.results || [],
    merchant_risk:   merchant,
    client_history:  client,
    sla:             sla,
    agent_analysis:  agentAnalysis,
    avisos_de_contexto: avisosDeContexto,
  }
}];

// Construir el payload exacto que espera POST /api/reports/html (ReportRequest)
const ctx        = $('Compilar Contexto').first().json;
const resolution = $('Sintetizar Resolución').first().json;
const judge      = $input.first().json.judge_evaluation || {
  overall_score: 5.0,
  criteria: {},
  approved: false,
  strengths: [],
  weaknesses: ['Judge evaluation unavailable'],
};

return [{
  json: {
    transaction:         ctx.tx_data,
    resolution:          resolution,
    judge_evaluation:    judge,
    agent_analysis:      ctx.agent_analysis,
    merchant_risk:       ctx.merchant_risk,
    client_profile:      ctx.client_history,
    logs:                ctx.logs,
    policies_evaluated:  resolution.policy_verdicts || [],
    similar_cases:       ctx.similar_cases,
    hitl_decision:       null,
    cache_hit:           false,
    // Del nodo que los verifica, con la resolucion como respaldo: `Verificar
    // Guardrails` tiene onError=continueRegularOutput, asi que si falla su salida
    // llega vacia. Sin el respaldo, el informe saldria sin los avisos — que son la
    // unica constancia de que el modelo se contradijo — y sin que nada lo delate.
    guardrail_warnings:  $('Verificar Guardrails').first().json._guardrails?.warnings
                         || resolution.guardrail_warnings || [],
    motivo:              ctx.motivo || '',
    cliente_vip:         ctx.cliente_vip || false,
    // El plazo con el que se decidio la compensacion, y que parte del contexto
    // no se pudo reunir. Los dos se mostraban solo por su conclusion.
    sla:                 ctx.sla || {},
    avisos_de_contexto:  ctx.avisos_de_contexto || [],
  }
}];

// Cache hit: return JSON with cached flag + HTML
const html = $input.first().json.html;
return [{ json: { cached: true, html } }];

// Hacer visibles en el canvas los guardrails que ya corrieron en la API.
//
// Antes este nodo recalculaba los umbrales (1.1, 0.95, 2 fails) copiados de
// domain/constants.py. Eran una segunda fuente de verdad que nadie leia: los
// nodos de abajo releen $('Sintetizar Resolucion'), no la salida de este.
// Ahora solo resume lo que la API ya decidio.
const resolution = $input.first().json;
const warnings   = resolution.guardrail_warnings || [];

return [{
  json: {
    ...resolution,
    _guardrails: {
      total: warnings.length,
      warnings: warnings,
      status: warnings.length > 0 ? 'GUARDRAILS ACTIVADOS' : 'Sin alertas',
    },
  }
}];

// Pega la decision del analista sobre el informe que YA se armo antes del Wait.
//
// Este nodo tenia 88 lineas: normalizaba la decision, mapeaba las tres opciones
// del formulario, resolvia el vencimiento del plazo y decidia que resolucion
// entraba al corpus de precedentes. Todo eso es logica de negocio y ahora vive
// en la API (`domain/hitl.py`, con tests). Aca queda lo que le toca a un
// orquestador: unir dos salidas.
//
// El payload del informe no se vuelve a armar. `Preparar Informe` ya lo
// construyo antes de derivar al Wait, asi que rehacerlo era la tercera copia de
// los mismos catorce campos.
const informe  = $('Preparar Informe').first().json;
const decidido = $input.first().json;

// Si la API no contesto, el nodo de arriba deja pasar un item de error. No se
// inventa una decision aca: eso seria devolver al canvas exactamente la logica
// que se le saco. El informe sale diciendo que la decision no se pudo registrar,
// y sin feedback no hay precedente que indexar — el mismo fallo cerrado.
const huboDecision = decidido && decidido.hitl_decision;

return [{
  json: {
    ...informe,
    hitl_decision:     huboDecision ? decidido.hitl_decision : null,
    _feedback_payload: huboDecision ? decidido.feedback : null,
    _hitl_sin_registrar: !huboDecision,
  }
}];
